const auditLogSchema = new mongoose.Schema({
  action: { type: String, enum: AUDIT_ACTIONS, required: true, index: true },
  // Which hospital this happened in (empty for platform-level events). Hospital admins only see
  // entries for their own hospital.
  tenantId: { type: mongoose.Schema.Types.ObjectId, ref: 'Tenant', default: null, index: true },
  // Who did it (empty for anonymous events such as a failed login).
  actor: { type: mongoose.Schema.Types.ObjectId, ref: 'User', default: null },
  actorEmail: { type: String, default: null },
  // Who it was done to (if anyone).
  target: { type: mongoose.Schema.Types.ObjectId, ref: 'User', default: null },
  targetEmail: { type: String, default: null },
  details: { type: mongoose.Schema.Types.Mixed, default: {} },
  ip: { type: String, default: null },
  userAgent: { type: String, default: null },
  createdAt: { type: Date, default: Date.now, index: true },
});

// Audit entries are append-only: block edits and deletes through the app.
for (const op of ['updateOne', 'updateMany', 'findOneAndUpdate', 'deleteOne', 'deleteMany', 'findOneAndDelete']) {
  auditLogSchema.pre(op, function () {
    throw new Error('Audit log entries cannot be changed or deleted');
  });
}

// Indexes keep the audit log fast even with millions of entries (newest first, per hospital/person/event).
auditLogSchema.index({ tenantId: 1, createdAt: -1 });
auditLogSchema.index({ action: 1, createdAt: -1 });
auditLogSchema.index({ actor: 1, createdAt: -1 });
auditLogSchema.index({ target: 1, createdAt: -1 });
// A visit's history (who saved, signed, corrected or printed it)
auditLogSchema.index({ tenantId: 1, 'details.visitId': 1, createdAt: 1 }, { partialFilterExpression: { 'details.visitId': { $exists: true } } });

auditLogSchema.set('toJSON', {
  transform(_doc, ret) {
    ret.id = ret._id.toString();
    delete ret._id;
    delete ret.__v;
    return ret;
  },
});

export const AuditLog = mongoose.model('AuditLog', auditLogSchema);
